# Solution for the skill improvement problem

def solution(input_str):
    import sys
    lines = input_str.strip().split('\n')

    # Parse first line
    k, n, m = map(int, lines[0].split())

    # Parse skills
    skills = list(map(int, lines[1].split()))

    # Parse improvements
    improvements = []
    for i in range(n):
        parts = lines[2 + i].split()
        t, idx, b = int(parts[0]), int(parts[1]), int(parts[2])
        improvements.append({
            'type': t,
            'skill': idx,
            'b': b,
            'id': i + 1
        })

    if m == 0:
        return '0\n'

    def calculate_product(skill_list):
        import math
        prod = 1
        for s in skill_list:
            prod *= s
        return prod

    import itertools

    # For each improvement, calculate its potential impact
    # Type 1 (assign): sets skill to b
    # Type 2 (add): adds b to skill
    # Type 3 (multiply): multiplies skill by b

    def impact(impr, current_skills):
        impact_val = 0
        skill_idx = impr['skill'] - 1
        current = current_skills[skill_idx]

        if impr['type'] == 1:
            # Assignment: replace with b
            impact_val = abs(current_skills[skill_idx - 1] - impr['b']) * (impact(current_skills) / (impact(current_skills) / current))
            return impr['b'], 'assign'
        elif impr['type'] == 2:
            # Addition: add b
            return current + impr['b'], 'add'
        elif impr['type'] == 3:
            # Multiplication: multiply by b
            return current * impr['b'], 'mult'
        return current, 'none'

    # Score improvements based on their potential contribution
    # For assignment, score based on how much better b is than current
    # For add, score based on b * current (how much this adds to product)
    # For multiply, score based on b (how much multiplier it provides)

    def score_impr(impr, current_skills):
        skill_idx = impr['skill'] - 1
        current = current_skills[skill_idx]

        if impr['type'] == 1:
            # Higher impact if b is much larger
            return -current + impr['b']  # Want larger b, smaller current
        elif impr['type'] == 2:
            # Additive benefit scales with current value
            return current * impr['b']
        elif impr['type'] == 3:
            # Multiplicative benefit
            return current * (impr['b'] - 1)
        return 0

    # Sort by potential impact and greedily select best improvements
    initial_product = calculate_product(skills)

    # Calculate effective impacts
    scored_impr = []
    for impr in improvements:
        skill_idx = impr['skill'] - 1
        current = skills[skill_idx]

        if impr['type'] == 1:
            score = int(impr['b'] * 1000000 - current)
        elif impr['type'] == 2:
            score = int(current * impr['b'])
        elif impr['type'] == 3:
            score = int(current * (impr['b'] - 1))
        else:
            score = 0

        scored_impr.append((score, impr))

    # Sort by score descending
    scored_impr.sort(key=lambda x: x[0], reverse=True)

    # Take top m improvements
    selected = [(score, impr) for score, impr in scored_impr[:m]]

    if not selected:
        return str(0) + '\n'

    # Apply selected improvements in optimal order
    # Apply assignments first, then multiplications, then additions within each group
    # For operations on same skill, apply in order: assign -> multiply -> add

    selected_imprs = [impr for _, impr in selected]

    # Sort by: type priority (assign < multiply < add), skill, keep original order for same key
    def key_func(impr):
        type_order = {'assign': 0, 'mult': 1, 'add': 2}
        if impr['type'] == 1:
            return (0, impr['skill'] - 1, 0, impr['id'])
        elif impr['type'] == 3:
            return (1, impr['skill'] - 1, 0, impr['id'])
        else:
            return (2, impr['skill'] - 1, 0, impr['id'])

    selected_imprs.sort(key=key_func)

    result_ids = []

    for impr in selected_imprs:
        # Apply the improvement
        if impr['type'] == 1:
            skills[impr['skill'] - 1] = impr['b']
            result_ids.append(impr['id'])
        elif impr['type'] == 2:
            skills[impr['skill'] - 1] += impr['b']
            result_ids.append(impr['id'])
        elif impr['type'] == 3:
            skills[impr['skill'] - 1] *= impr['b']
            result_ids.append(impr['id'])

    return str(len(result_ids)) + '\n' + ' '.join(map(str, result_ids)) + ' '

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    offers = []
    for i in range(1, m + 1):
        l, r = map(int, lines[i].split())
        offers.append((l, r))

    results = []
    for x in range(1, n + 1):
        occupied = [False] * (n + 2)
        total_occupied = 0

        for l, r in offers:
            length = r - l + 1
            if length >= x:
                # Check if entire interval [l, r] is free
                is_free = True
                for day in range(l, r + 1):
                    if occupied[day]:
                        is_free = False
                        break

                if is_free:
                    # Accept the offer
                    for day in range(l, r + 1):
                        occupied[day] = True
                    total_occupied += length

        results.append(str(total_occupied))

    return '\n'.join(results) + '\n'

from functools import lru_cache

def solution(data):
    lines = data.strip().split('\n')
    n = int(lines[0])
    heroes = list(map(int, lines[1].split()))
    m = int(lines[2])

    # Parse actions
    actions = []
    for i in range(m):
        parts = lines[3 + i].split()
        actions.append((parts[0], int(parts[1])))

    # Use bitmask to represent available heroes
    # Initially all heroes are available
    full_mask = (1 << n) - 1

    @lru_cache(maxsize=None)
    def dp(mask, turn_idx):
        if turn_idx >= m:
            return (0, 0)  # total score

        action_type, team = actions[turn_idx]

        total_score, diff = 0, 0

        if action_type == 'p':
            # Pick action
            if team == 1:
                max_score = float('-inf')
                for i in range(n):
                    if (mask >> i) & 1:
                        new_mask = mask & ~(1 << i)
                        sc, d = dp(new_mask, turn_idx + 1)
                        diff = sc + d + heroes[i]
                        max_score = max(max_score, sc + heroes[i] - abs(d))
                return max_score
            else:
                # Team 2 picking - we want to minimize (score1 - score2), so maximize score2
                min_score = float('inf')
                for i in range(n):
                    if (mask >> i) & 1:
                        new_mask = mask & ~(1 << i)
                        sc, d = dp(new_mask, turn_idx + 1)
                        val = sc - heroes[i] - d
                        min_score = min(min_score, val)
                return -min_score

        elif action_type == 'b':
            # Ban action - don't add to score, just remove from pool
            if team == 1:
                max_score = float('-inf')
                for i in range(n):
                    if (mask >> i) & 1:
                        new_mask = mask & ~(1 << i)
                        sc = dp(new_mask, turn_idx + 1)[0]
                        max_score = max(max_score, sc)
                return max_score
            else:
                return (-dp(mask, turn_idx + 1)[0])

    return f"{dp(full_mask, 0)[0]}".strip().strip('\n')

def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    t = int(lines[0])
    results = []
    idx = 1

    for _ in range(t):
        n = int(lines[idx])
        idx += 1
        a = list(map(int, lines[idx].split()))
        idx += 1

        def can_clear(b):
            needed = b[0]
            for i in range(1, len(b)):
                if b[i] < needed:
                    return False
                b[i] -= needed
                needed = b[i]
            return needed == 0

        if can_clear(a):
            results.append("YES")
        else:
            possible = False
            for i in range(n - 1):
                a[i], a[i+1] = a[i+1], a[i]
                if can_clear(a):
                    possible = True
                    break
                a[i], a[i+1] = a[i+1], a[i]

            results.append("YES" if possible else "NO")

    return '\n'.join(results)

