        n, m = map(int, lines[idx].split())
        idx += 1

        xor_sum = 0
        for _ in range(n):
            if idx >= len(lines):
                break
            # Read the row values
            if len(lines) - idx >= m:
                row_values = list(map(int, lines[idx].split()))
                idx += 1
                for val in row_values:
                    xor_sum ^= val
            else:
                break

        if xor_sum != 0:
            results.append('Ashish')
        else:
            results.append('Jeel')

    return '\n'.join(results)

