def find_k_cycles(adj, n, k):
    """Find k cycles with length >= 3 and not divisible by 3, each with a unique representative."""
    cycles = []
    used_reps = set()

    # We'll use DFS to find cycles
    stack = [(i, -1, 0, [i]) for i in range(1, n + 1)]
    dfs_visited = [False] * (n + 1)

    while stack and len(cycles) < k:
        node, parent, depth, path = stack.pop()

        if dfs_visited[node]:
            continue
        dfs_visited[node] = True

        found_cycle = False
        for neighbor in adj[node]:
            if neighbor == parent:
                continue

            # Check if neighbor is in current path (back edge found)
            try:
                idx = path.index(neighbor)
                cycle_len = len(path) - idx
                if cycle_len >= 3 and cycle_len % 3 != 0:
                    # Found a valid cycle
                    cycle = path[idx:] + [neighbor]
                    cycle_reps = cycle[:dfs_len]
                    cycle_reps = []
                    for i in range(2, len(cycle)):
                        rep_candidate = cycle[i]
                        if rep_candidate not in used_reps:
                            used_reps.add(rep_candidate)
                            cycle_reps.append(rep_candidate)
                            if len(cycle_reps) >= 1:
                                break

                    cycles.append(cycle[0])
                    found_cycle = True
                    break
            except ValueError:
                pass

            if not dfs_visited[neighbor]:
                stack.append((neighbor, node, depth + 1, path + [neighbor]))

    if not cycles:
        # Try DFS from each unvisited vertex more systematically
        dfs_visited = [False] * (n + 1)
        for root in range(1, n + 1):
            if dfs_visited[root]:
                continue

            path_stack = [root]
            dfs_visited[root] = True
            path = [root]

            while path_stack and len(cycles) < k:
                u = path_stack[-1]

                # Find first unvisited or back-edge neighbor
                found = False
                for v in adj[u]:
                    if v == path[-2] if len(path) > 1 else -1:
                        continue
                    if v in path or dfs_visited[v]:
                        if v in path:
                            # Back edge found
                            idx = path.index(v)
                            cycle_len = len(path) - idx
                            if cycle_len >= 3 and cycle_len % 3 != 0:
                                cycle = path[idx:] + [v]
                                # Add representative
                                cycle[0] = v
                                cycles.append(cycle[0])
                                dfs_visited[v] = True
                                found = True
                                break

                    if not dfs_visited[v]:
                        dfs_visited[v] = True
                        path.append(v)
                        path_stack.append(v)
                        found = True
                        break

                if not found:
                    path_stack.pop()
                    path.pop()

    # If we didn't get k cycles, return empty
    if len(cycles) < k:
        cycles = []

    return cycles, used_reps


def find_long_path(adj, n, k):
    """Find a simple path with length at least n/k."""
    target_len = (n / k)

    # Find a vertex with high degree to start DFS
    for start in range(1, n + 1):
        if len(adj[start]) >= 3:
            result = find_len_path(adj, start, target_len)
            if result:
                return (result, len(result))

    return None


def find_len_path(adj, start, target_len):
    """DFS to find longest simple path from start."""
    max_len = 0
    max_path = []

    visited = [False] * (n + 1)

    def dfs(u, path):
        nonlocal max_len, max_path

        if len(path) > max_len:
            max_len = len(path)
            max_path = path[:]

        if len(path) >= target_len * (4/3):  # Conservative check
            return None

        visited[u] = True
        path.append(u)

        for v in adj[u]:
            if not visited[v]:
                res = dfs(v, path)
                if res is not None:
                    return res

        path.pop()
        visited[u] = False

    # Try multiple starting points
    for start in range(1, n + 1):
        visited = [False] * (n + 1)
        dfs(start, [start])
        if max_len >= target_len:
            return max_path

    return None


