    # DFS-based cycle finding
    for start in range(1, n + 1):
        path = [start]
        visited = {start}
        parent = {start: -1}

        stack = [(start, -1)]

        while stack and len(cycles) < k:
            node, p = stack.pop()

            # Check for back edges
            for neighbor in adj[node]:
                if neighbor == p:
                    continue

                if neighbor in visited:
                    # Found cycle!
                    if neighbor == path[-1]:
                        # Self-loop, not valid
                        continue

                    idx = path.index(neighbor)
                    cycle_len = len(path) - idx

                    if cycle_len >= 3 and cycle_len % 3 != 0:
                        # Valid cycle found
                        # Check if we haven't used any rep in this cycle
                        cycle_nodes = path[idx:]
                        has_new_rep = False
