                            if rep not in used_reps:
                                used_reps.add(rep)
                                cycles.append(cycle_nodes + [reps if retries > 0 else neighbor])
                                cycles.append(cycle_nodes + [neighbor])
                                # We already checked for new rep
                                cycles.append(cycle_nodes)
                                break
                        else:
                            cycles.append(cycle_nodes)

                    if len(cycles) >= k:
                        break
                else:
                    visited.add(neighbor)
                    parent[neighbor] = node
                    stack.append((neighbor, node))

        if len(cycles) >= k:
            break

    # Rebuild cycles properly
    final_cycles = []
    for start in range(1, n + 1):
        if len(cycles) >= k:
            break

        visited = [False] * (n + 1)
        path = []
        stack = [start]
        visited[start] = True

        while stack and len(cycles) < k:
            node = stack[-1]

            found_new = False
            for neighbor in adj[node]:
                if neighbor in visited:
                    if neighbor != path[-1] if path else True:
                        # Back edge
                        try:
                            idx = path.index(neighbor)
                            cycle_len = len(path) - idx
                            if cycle_len >= 3 and cycle_len % 3 != 0:
                                cycle = path[idx:] + [neighbor]
                                rep = cycle[-1]
                                if rep not in used_reps:
                                    used_reps.add(rep)
                                    final_cycles.append(cycle[:])
                                    found_new = True
                                    break
                        except:
                            pass

                if not found_new and not visited[neighbor]:
                    visited[neighbor] = True
                    path.append(neighbor)
