def improve_cycles(adj, n, k):
    """Improved cycle finding with better DFS."""
    cycles = []
    used_reps = set()

    # For each unvisited node, try to find a cycle
    visited_global = [False] * (n + 1)

    def dfs(u, p, depth, path):
        for v in adj[u]:
            if v == p:
                continue

            if v in path:
                # Back edge to ancestor - found a cycle
                idx = path.index(v)
                cycle_len = len(path) - idx

                if cycle_len >= 3 and cycle_len % 3 != 0:
                    # Check if any vertex in this cycle can be a fresh rep
                    cycle_nodes = path[idx:] + [v]
                    fresh_rep = None
                    for node in cycle_nodes:
