    for start in range(1, n + 1):
        if start in used_reps:
            continue

        visited_local = {start}
        path = [start]
        parent_map = {start: -1}
        stack = [start]

        while stack and len(cycles) < k:
            node = stack[-1]

            found = False
            for neighbor in adj[node]:
                if neighbor == parent_map[node]:
                    continue

                if neighbor in visited_local:
                    # Back edge
                    try:
                        idx = path.index(neighbor)
                        cycle_len = len(path) - idx
                        if cycle_len >= 3 and cycle_len % 3 != 0:
                            cycle = path[idx:] + [neighbor]
                            rep = cycle[0]
                            if rep not in used_reps:
                                used_reps.add(rep)
                                cycles.append(cycle)
                            found = True
