def find_k_cycles(adj, n, k):
    cycles = []
    used_reps = set()
    visited_global = [False] * (n + 1)

    for root in range(1, n + 1):
        if len(cycles) >= k or visited_global[root]:
            continue

        path = [root]
        visited = {root}
        parent_map = {root: -1}
        stack = [root]

        while stack and len(cycles) < k:
            node = stack[-1]

            found = False
            for neighbor in adj[node]:
                if neighbor == parent_map[node]:
                    continue

                if neighbor in visited:
                    idx = path.index(neighbor)
                    cycle_len = len(path) - idx

                    if cycle_len >= 3 and cycle_len % 3 != 0:
                        cycle = path[idx:]
                        rep = cycle[0]

                        # Try to find a fresh representative
                        rep_found = False
                        for rep_node in cycle:
                            if rep_node not in used_reps:
                                used_reps.add(rep_node)
                                rep_found = True
                                cycles.append(cycle)
                                break

                        found = True
                        break

                if not found and neighbor not in visited:
                    visited.add(neighbor)
                    parent_map[neighbor] = node
                    path.append(neighbor)
                    stack.append(neighbor)
                    found = True

            if not found:
                if len(path) > 1:
                    stack.pop()
                    path.pop()

        visited_global[root] = True

    return cycles if len(cycles) >= k else []


def find_long_path(adj, n, k):
    target = n / k + 1e-9

    def dfs(u, path, visited_set):
        if len(path) > len(max_path):
            max_path[:] = path[:]

        if len(path) >= target:
            return True

        for v in adj[u]:
            if v not in visited_set:
                visited_set.add(v)
                path.append(v)
                if dfs(v, path, visited_set):
                    return True
                path.pop()
                visited_set.remove(v)

        return False

    max_path = []
    for start in range(1, n + 1):
        visited = {start}
        dfs(start, [start], visited)
        if len(max_path) >= target:
            break

    return max_path[:int(n/k)+1]


