    lazy_tree = [0.0] * (2 * size)

    for i in range(n):
        tree[size + i] = a[i]

    for i in range(size - 1, 0, -1):
        tree[i] = tree[2*i] + tree[2*i+1]

    def push(v):
        if lazy_tree[v] != 0:
            lazy_tree[2*v] += lazy_tree[v]
            lazy_tree[2*v+1] += lazy_tree[v]
            tree[2*v] += lazy_tree[v] * (size - (2*v - 1) if 2*v <= n else 1)
            tree[2*v+1] += lazy_tree[v] * (size - (2*v - 2) if 2*v+1 <= n else 1)
            lazy_tree[v] = 0

    def update(v, tl, tr, l, r, x):
        if l <= tl and tr <= r:
            tree[v] += x * (tr - tl + 1)
            lazy_tree[v] += x
            return
        push(v)
        tm = (tl + tr) // 2
        if l <= tm:
            update(2*v, tl, tm, l, r, x)
        if r > tm:
            update(2*v+1, tm+1, tr, l, r, x)
        tree[v] = tree[2*v] + tree[2*v+1]

