def solution(input_str):
    from collections import deque

    input_str = input_str.strip()
    if not input_str:
        return '0'

    lines = input_str.split('\n')

    if not lines[0].strip():
        return '0'

    n, m = map(int, lines[0].split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i < len(lines):
            line = lines[i].strip()
            if line:
                u, v = map(int, line.split())
                adj[u].append(v)
                adj[v].append(u)

    # Get x array  
    idx = 1 + m
    if idx < len(lines):
        x = list(map(int, lines[idx].strip().split()))
    else:
        x = [0] * n

    # If no odd requirements, empty path
    if sum(x) == 0:
        return '0'

    # If no edges
    if m == 0:
        return '-1'

    odd_v = [i + 1 for i in range(n) if x[i] == 1]

    # If odd count of odd-requirement vertices, impossible
    if len(odd_v) % 2 != 0:
        return '-1'

    # Handle case with exactly 2 odd vertices
    if len(odd_v) == 2:
        u, v = odd_v[0], odd_v[1]
        if u == v:
            return '1\n' + str(u)

        # BFS from u to find path to v
        dist = {i: float('inf') for i in range(1, n + 1)}
        parent = {i: None for i in range(1, n + 1)}
        dist[u] = 0
        queue = deque([u])

        while queue:
            curr = queue.popleft()
            if curr == v:
                break

            for neighbor in adj[curr]:
                if dist[neighbor] == float('inf'):
                    dist[neighbor] = dist[curr] + 1
                    parent[neighbor] = curr
                    queue.append(neighbor)

        if dist[v] == float('inf'):
            return '-1'

        # Reconstruct path from v to u
        path = []
        curr = v
        while curr is not None:
            path.append(curr)
            curr = parent[curr]
        path.reverse()

        return f'{len(path)}\n{" ".join(map(str, path))}'

    # Handle more than 2 odd vertices
    if len(odd_v) > 2:
        if len(odd_v) % 2 != 0:
            return '-1'

        for i in range(len(odd_v)):
            for j in range(i + 1, len(odd_v)):
                start = odd_v[i]
                end = odd_v[j]

                if start == end:
                    return '1\n' + str(start)

                dist = {k: float('inf') for k in range(1, n + 1)}
                parent = {k: None for k in range(1, n + 1)}
                dist[start] = 0
                queue = deque([start])

                while queue:
                    curr = queue.popleft()
                    if curr == end:
                        break

                    for neighbor in adj[curr]:
                        if dist[neighbor] == float('inf'):
                            dist[neighbor] = dist[curr] + 1
                            parent[neighbor] = curr
                            queue.append(neighbor)

                if dist[end] == float('inf'):
                    continue

                # Reconstruct
                path = []
                curr = end
                while curr is not None:
                    path.append(curr)
                    curr = parent[curr]
                path.reverse()

                return f'{len(path)}\n{" ".join(map(str, path))}'

        return '-1'

    return '-1'

