class Parser:
    def __init__(self, s):
        self.s = s
        self.pos = 0
        MOD = 10**9 + 7

    def parse(self):
        return self.parse_expression()

    def parse_expression(self):
        result = self.parse_term()
        while self.pos < len(self.s) and self.s[self.pos] == '+':
            self.pos += 1
            result = self.concat(result, self.parse_term(), MOD)
        return result

    def parse_term(self):
        if self.s[self.pos] == '(':
            self.pos += 1
            inner = self.parse_expression()
            self.pos += 1  # skip ')'

            length = self.parse_number()
            return self.repeat_value(length, inner, MOD)

        # Check if it's a number followed by '-' another number (range)
        start_idx = self.pos
        while self.pos < len(self.s) and self.s[self.pos].isdigit():
            self.pos += 1

        start = int(''.join(self.s[start_idx:self.pos]))

        if self.pos < len(self.s) and self.s[self.pos] == '-':
            self.pos += 1  # skip '-'
            end_idx = self.pos
            while self.pos < len(self.s) and self.s[self.pos].isdigit():
                self.pos += 1

            end = int(''.join(self.s[end_idx:self.pos]))
            if start <= end:
                return self.concat_range(start, end, MOD)
            return start

        return start

    def parse_number(self):
        start = self.pos
        while self.pos < len(self.s) and self.s[self.pos].isdigit():
            self.pos += 1
        num_str = self.s[start:self.pos]
        return int(num_str)

    def concat(self, a_str, b_str, MOD):
        # Concatenate a_str + b_str modulo 10^9 + 7
        len_a = len(a_str)
        len_b = len(b_str)

        a_num = int(a_str) % MOD if a_str else 0
        b_num = int(b_str) % MOD if b_str else 0

        result = (a_num * 10**len_b + b_num) % MOD

        # Return the string and length for further concatenation
        return (result, len(a_str) + len(b_str))

    def repeat_value(self, times, inner_info, MOD):
        a_str = inner_info[0]
        a_len = len(str(a_str)) if isinstance(a_str, int) else 0

        # Compute a_str repeated n times
        result = 0
        current_len = 0

        for _ in range(times):
            result = (result * pow(10, a_len, MOD) + a_str) % MOD
            current_len += a_len

        return (result, current_len)

    def concat_range(self, start, end, MOD):
        result = 0
        current_len = 0

        for i in range(start, end + 1):
            num_str = str(i)
            num_val = int(num_str)
            result = (result * pow(10, len(num_str), MOD) + num_val) % MOD
            current_len += len(num_str)

        return (result, current_len)


