    For each test case, we need to count the unique transformation pairs
    (character in A, character in B) where they differ.
    """
    lines = input_str.strip().split('\n')
    idx = 0

    # Handle empty input
    if not lines or idx >= len(lines):
        return ''

    try:
        t = int(lines[idx].strip())
    except:
        return ''

