        if idx >= len(lines):
            break

        try:
            n_line = lines[idx].strip()
            if not n_line:
                break
            n = int(n_line)
            idx += 1

            a = lines[idx].strip()
            idx += 1
            b = lines[idx].strip()
            idx += 1
        except:
            break

        # Count unique transformation pairs where A[i] != B[i]
        edges = set()
        for i in range(n):
            if a[i] != b[i]:
                edges.add((a[i], b[i]))

        results.append(str(len(edges)))

    return '\n'.join(results)


