from collections import defaultdict
MOD = 10**9 + 7


def solution(data):
    input_lines = data.strip().split('\n')
    n = int(input_lines[0])
    a = list(map(int, input_lines[1].split()))

    if n == 1:
        return '1'

    def get_square_free(x):
        result = x
        d = 2
        while d * d <= result:
            count = 0
            while result % d == 0:
                count += 1
                result //= d
            if count % 2 == 1:
                break
            d += 1
        return result

    groups = defaultdict(list)
    for num in a:
        sf = get_square_free(num)
        groups[sf].append(num)

    group_sizes = [len(v) for v in groups.values()]
    total = len(a)

    if total == 0:
        return '0'

    if len(group_sizes) == 1 and group_sizes[0] > 1:
        return '0'

    from functools import lru_cache

    sorted_sizes = sorted(group_sizes, reverse=True)
    k = len(sorted_sizes)
    m = total

    if k == 1:
        return '0'

    @lru_cache(maxsize=None)
    def dp(mask, c_idx, current_pos, prev_group, in_group):
        if c_idx == len(sorted_sizes):
            return 1

        if mask == (1 << k) - 1:
            return dp_any

        if mask == 0:
            # Place elements of first group
            return place_group(0, current_pos + sorted_sizes[0], 0, total, 0, sorted_sizes[0], current_pos + sorted_sizes[0], sorted_sizes[0],
                           sorted_sizes[0], sorted_sizes[0]) % MOD

        ways = 0
        return ways

    # Use iterative DP instead of recursion
    def factorial_mod(i, mod):
        if i <= 0:
            return 1
        result = 1
        for x in range(2, i + 1):
            result = (result * x) % mod
        return result

    def power_mod(a, b, mod):
        result = 1
        a %= mod
        while b > 0:
            if b % 2 == 1:
                result = (result * a) % mod
            a = (a * a) % mod
            b //= 2
        return result

    def nCr_mod(n, r, mod):
        if r < 0 or r > n:
            return 0
        fact = [1] * (n + 1)
        for i in range(2, n + 1):
            fact[i] = (fact[i-1] * i) % mod
        num = fact[n]
        den = (fact[r] * fact[n-r]) % mod
        return (num * power_mod(den, mod - 2, mod)) % mod

    def place_group(idx, prev_idx, curr, dp, M):
        S = sorted_sizes[idx]
        new_dp = [0] * (prev_idx + S + 1)

        for p in range(prev_idx + 1):
            if dp[p] <= 0:
                continue

            # Insert S elements into M positions
            for i in range(S + 1):
                if p + i <= len(dp) - 1:
                    if i > 0:
                        ways = (dp[p] * nCr_mod(M, i + p, M)) % MOD
                        new_dp[p + i] = (new_dp[p + i] + ways) % MOD

        dp[:] = new_dp[:len(dp)]

    # Use simpler DP approach
    dp = [1] + [0] * m

    for size in sorted_sizes:
        if size == 0:
            continue
        new_dp = [0] * max(len(dp), size + 1)

        # Insert 'size' elements
        for prev in range(len(dp)):
            if dp[prev] == 0:
                continue

            for insert in range(size + 1):
                if prev + insert > m:
                    break

                # Calculate how many ways
                remaining = m - prev
                if remaining >= insert:
                    ways = nCr_mod(remaining, insert, MOD)
                    term = (dp[prev] * ways) % MOD
                    new_dp[prev + insert] = (new_dp[prev + insert] + term) % mod

        dp = new_dp
        m = m + sum(sorted_sizes) - sum(sorted_sizes[:sorted_sizes.index(size)])

    return str(sum(dp))

import math

def solution(input_data):
    lines = input_data.strip().split('\n')
    n = int(lines[0])
    centers = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        centers.append((float(x), float(y)))

    # If fewer than 3 circles, no holes can be formed
    if n < 3:
        return '-1\n'

    def dist(p1, p2):
        return math.hypot(p1[0] - p2[0], p1[1] - p2[1])

    def circumcenter(p1, p2, p3):
        """Calculate circumcenter of triangle formed by three points"""
        x1, y1 = p1
        x2, y2 = p2
        x3, y3 = p3

        # Using standard circumcenter formula
        d = 2 * (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2))
        if abs(d) < 1e-9:
            # Collinear points - no circumcircle
            return None

        ux = ((x1**2 + y1**2) * (y2 - y3) + 
              (x2**2 + y2**2) * (y3 - y1) + 
              (x3**2 + y3**2) * (y1 - y2)) / d

        uy = ((x1**2 + y1**2) * (x3 - x2) + 
              (x2**2 + y2**2) * (x1 - x3) + 
              (x3**2 + y3**2) * (x2 - x1)) / d

        return (ux, uy)

    def max_radius_from_3_centers(p1, p2, p3):
        """Find maximum distance from circumcenter to any of the three centers"""
        c = circumcenter(p1, p2, p3)
        if c is None:
            return float('inf')  # Skip collinear case

        return max(dist(c, p1), dist(c, p2), dist(c, p3))

    max_time = 0.0

    # Check all triplets of circles
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                r = max_radius_from_3_centers(centers[i], centers[j], centers[k])
                if r is not float('inf'):
                    max_time = max(max_time, r)

    if max_time < 1e-9:
        # No valid hole configuration found (all triplets are collinear or invalid)
        return '-1\n'

    return f"{max_time:.6f}\n"

