def solution(input_str):
    MOD = 10**9 + 7
    MAX_N = 1000001

    # Precompute factorials and their modular inverses
    fact = [1] * MAX_N
    inv = [1] * MAX_N

    for i in range(1, MAX_N):
        fact[i] = (fact[i-1] * i) % MOD

    inv[MAX_N - 1] = pow(fact[MAX_N - 1], MOD - 2, MOD)
    for i in range(MAX_N - 2, 1, -1):
        inv[i] = (inv[i+1] * (i+1)) % MOD

    def nCr_mod(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv[r] % MOD * inv[n - r] % MOD

    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    q = int(lines[0].strip())

    results = []

    for i in range(1, q + 1):
        parts = lines[i].strip().split()
        r = int(parts[0])
        n = int(parts[1])

        if n == 1:
            results.append('1')
            continue

        if r == 0:
            # f0(n) = 2^omega(n)
            omega = 0
            temp = n
            d = 2
            while d * d <= temp:
                while temp % d == 0:
                    omega += 1
                    temp //= d
                d += 1
            if temp > 1:
                omega += 1
            ans = pow(2, omega, MOD)
            results.append(str(ans))
        else:
            # fr(p^k) = C(k + r, r) * 2^k
            ans = 1
            temp = n
            d = 2
            while d * d <= temp:
                if temp % d == 0:
                    k = 0
                    while temp % d == 0:
                        k += 1
                        temp //= d
                    term = nCr_mod(k + r, r) * pow(2, k, MOD)
                    ans = (ans * term) % MOD
                d += 1
            if temp > 1:
                k = 1
                term = nCr_mod(k + r, r) * pow(2, k, MOD)
                ans = (ans * term) % MOD
            results.append(str(ans))

    return '\n'.join(results)


