        inv_change = between_less - between_greater - (1 if val_a > val_b else 0)

        inv_count += inv_change

        # Perform the swap
        perm[a], perm[b] = val_b, val_a

        results.append(str(inv_count))

    return '\n'.join(results) + '\n'

